import {closeDialog} from './ui-motion.js';
const $=s=>document.querySelector(s),form=$('#join-form'),status=$('#social-status'),people=$('#social-people'),roomInput=$('#room-code'),nameInput=$('#visitor-name'),passwordInput=$('#room-password'),studio=$('#studio');
const invited=new URL(location.href).searchParams.get('room');let room=/^[a-zA-Z0-9_-]{8,48}$/.test(invited||'')?invited:'winter-plaza',joined=false,admin=false,busy=false,gesture='',failures=0,inviteURL='';roomInput.value=room;
try{nameInput.value=localStorage.getItem('winter-visitor-name')||'';}catch{}
function setName(name){nameInput.value=name;$('#profile-name').value=name;$('#self-name').textContent=name;try{localStorage.setItem('winter-visitor-name',name);}catch{}}
async function request(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(8000)});const data=await r.json();if(!r.ok){const e=Error(data.error||'연결을 확인해 주세요.');e.status=r.status;throw e;}return data;}
function showPeople(list){people.replaceChildren();list=list.filter(p=>!window.isVisitorBlocked?.(p.id));for(const person of list){const li=document.createElement('li');li.textContent=person.name+(person.gesture==='wave'?' · 인사':'');const block=document.createElement('button');block.textContent='차단';block.dataset.blockVisitor=person.id;block.setAttribute('aria-label',person.name+' 차단');li.append(block);people.append(li);}window.dispatchEvent(new CustomEvent('lab:visitors',{detail:list}));}
function openInvite(gate=false){$('#open-social').click();document.body.classList.toggle('invite-gate',gate);if(gate){$('.studio-head>span').textContent='YIWON';$('#invite-description').textContent='닉네임과 비밀번호를 입력하세요.';}}
function endGate(){document.body.classList.remove('invite-gate');$('.studio-head>span').textContent='다른 공간';}
studio.addEventListener('cancel',e=>{if(document.body.classList.contains('invite-gate'))e.preventDefault();});
function entered(data){room=data.room;roomInput.value=room;joined=true;window.labSocialJoined=true;failures=0;setName(data.name);passwordInput.value='';$('#leave-room').hidden=false;$('#wave').hidden=false;form.hidden=true;$('#profile-form').hidden=false;status.textContent='접속 중 · 1명';endGate();window.dispatchEvent(new CustomEvent('lab:room',{detail:room}));}
async function join(password){const data=await request('join',{name:nameInput.value,room:roomInput.value,password});entered(data);await sync();}
form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;status.textContent='입장 중…';try{await join(passwordInput.value);closeDialog(studio);}catch(e){status.textContent=e.message;}finally{button.disabled=false;}});
async function sync(){if(!joined||busy||document.hidden||!window.labPlayerState)return;busy=true;try{const a=window.labAppearance||{},data=await request('presence',{...window.labPlayerState,color:a.fur,accessory:a.accessory,gesture});gesture='';failures=0;showPeople(data.people);status.textContent='접속 중 · '+data.count+'명';}catch(e){failures++;if(e.status===401){joined=false;window.labSocialJoined=false;showPeople([]);form.hidden=false;if(invited)openInvite(true);}status.textContent=e.message;if(failures>2)showPeople([]);}finally{busy=false;}}
$('#leave-room').onclick=async()=>{joined=false;window.labSocialJoined=false;showPeople([]);chatLog.replaceChildren();seenChats.clear();selfBubble.hidden=true;try{await request('leave',{});}catch{}status.textContent='연결 종료';$('#leave-room').hidden=true;$('#wave').hidden=true;form.hidden=!invited;};
$('#wave').onclick=()=>{if(!joined)return;gesture='wave';window.parkCelebrate?.();sync();};
$('#invite-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('#invite-result').textContent='링크를 만드는 중…';try{const data=await request('invite',{password:$('#invite-password').value});inviteURL=data.url;roomInput.value=data.room;$('#invite-url').value=inviteURL;$('#invite-url').hidden=false;$('#copy-room').hidden=false;$('#enter-owned-room').hidden=false;$('#invite-password').value='';$('#invite-result').textContent='링크와 방금 정한 비밀번호를 전달하세요.';}catch(e){$('#invite-result').textContent=e.message;}finally{button.disabled=false;}});
$('#copy-room').onclick=async()=>{try{await navigator.clipboard.writeText(inviteURL);$('#invite-result').textContent='링크를 복사했습니다.';}catch{$('#invite-url').select();$('#invite-result').textContent='선택된 링크를 복사하세요.';}};
$('#enter-owned-room').onclick=async()=>{try{await join();history.replaceState(null,'','?room='+room);closeDialog(studio);}catch(e){status.textContent=e.message;}};
setInterval(sync,1000);window.addEventListener('pagehide',()=>{if(joined)navigator.sendBeacon('/api/leave','{}');});
const chatForm=$('#chat-form'),chatInput=$('#chat-input'),chatStatus=$('#chat-status'),chatToggle=$('#chat-toggle'),chatLog=$('#chat-log'),selfBubble=$('#self-bubble');
const seenChats=new Set(),blocked=new Set();
let chatMotion=null;
function openChat(){chatMotion?.cancel();chatMotion=null;if(!joined){openInvite(!!invited);return;}chatForm.hidden=false;chatToggle.setAttribute('aria-expanded','true');window.dispatchEvent(new Event('lab:pause'));chatInput.focus();}
function closeChat(){chatToggle.setAttribute('aria-expanded','false');chatInput.blur();if(!chatForm.animate||matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('still')){chatForm.hidden=true;return;}chatMotion?.cancel();const motion=chatForm.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(10px)'}],{duration:160,easing:'ease-in'});chatMotion=motion;motion.finished.then(()=>{if(chatMotion===motion){chatForm.hidden=true;chatMotion=null;}}).catch(()=>{});}
chatToggle.onclick=()=>chatForm.hidden?openChat():closeChat();
window.addEventListener('keydown',e=>{if(e.isComposing||document.body.classList.contains('studio-open')||document.body.classList.contains('quiz-open'))return;if(e.key==='Escape'&&!chatForm.hidden){closeChat();return;}if(e.key==='Enter'&&e.target!==chatInput&&!e.target.closest?.('input,textarea,button,a,summary')){e.preventDefault();openChat();}});
function record(name,message,key){if(seenChats.has(key))return;seenChats.add(key);if(seenChats.size>300)seenChats.delete(seenChats.values().next().value);const row=document.createElement('p'),author=document.createElement('b');author.textContent=name+' ';row.append(author,document.createTextNode(message));row.dataset.expires=String(Date.now()+6500);chatLog.append(row);while(chatLog.children.length>20)chatLog.firstElementChild.remove();chatLog.scrollTop=chatLog.scrollHeight;}
async function ensureChatSession(){if(joined)return;if(admin){await join();return;}openInvite(!!invited);throw Error('초대 링크로 입장해 주세요.');}
chatForm.addEventListener('submit',async e=>{e.preventDefault();if(e.isComposing)return;const message=chatInput.value.trim();if(!message)return;const send=chatForm.querySelector('[type=submit]');send.disabled=true;try{await ensureChatSession();const data=await request('chat',{message});chatInput.value='';chatStatus.textContent='';setName(data.name);record(data.name,data.message,'self:'+data.at);selfBubble.textContent=data.message;selfBubble.dataset.until=String(Date.now()+6500);selfBubble.hidden=false;closeChat();}catch(err){chatStatus.textContent=err.message;}finally{send.disabled=false;}});
window.addEventListener('lab:visitors',e=>{for(const p of e.detail)if(p.chat&&Date.now()-p.chatAt<6500&&!blocked.has(p.id))record(p.name,p.chat,p.id+':'+p.chatAt);});
window.isVisitorBlocked=id=>blocked.has(id);people.addEventListener('click',e=>{const b=e.target.closest('[data-block-visitor]');if(!b)return;blocked.add(b.dataset.blockVisitor);b.closest('li')?.remove();sync();});
setInterval(()=>{for(const row of chatLog.children){const remaining=Number(row.dataset.expires)-Date.now();row.style.opacity=String(Math.max(0,Math.min(1,remaining/700)));if(remaining<=0)row.remove();}},150);
window.joinSharedActivity=ensureChatSession;window.sharedRoom=()=>room;
async function initialize(){try{const access=await request('access');admin=access.admin;$('#admin-invite').hidden=!admin;$('#owner-signin').hidden=admin;form.hidden=admin||!invited;$('#invite-description').textContent=admin?'비밀번호를 정하고 링크를 공유하세요.':'관리자에게 받은 초대 링크로 입장하세요.';if(access.session&&(!invited||access.session.room===invited)){entered(access.session);}else if(admin){if(!nameInput.value)nameInput.value='YIWON';await join();}else if(invited){openInvite(true);}else if(access.signedIn){$('#owner-signin').hidden=true;}}catch(e){status.textContent=e.message;if(invited)openInvite(true);}}
initialize();

$('#profile-form').addEventListener('submit',async e=>{e.preventDefault();try{const data=await request('name',{name:$('#profile-name').value});setName(data.name);status.textContent='닉네임을 저장했습니다.';}catch(e){status.textContent=e.message;}});
